import React, { useState } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import ManageTeachers from './ManageTeachers';
import TeachersList from './TeachersList';


ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function LmsDashboard({ handleLogout }) {
  const [currentSubPage, setCurrentSubPage] = useState('Overview');

  const menuItems = [
    { name: 'Overview', icon: '📊' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' }
  ];

  const stats = { totalStudents: '1,250', totalTeachers: '45', activeClasses: '120', inactiveStudents: '25' };

  const growthData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May'],
    datasets: [{
      label: 'Enrollment Growth',
      data: [10, 32, 25, 48, 80],
      borderColor: '#15803d',
      backgroundColor: 'rgba(21, 128, 61, 0.1)',
      tension: 0.4,
      fill: true
    }]
  };

 // LmsDashboard.jsx

return (
  <div style={{ display: 'flex', flexDirection: 'column', flex: 1, backgroundColor: '#f8fafc' }}>
      
      {/* 1. අලුත් Header තීරුව (Welcome සහ Logout වෙනම තියෙන) */}
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        padding: '30px 40px', // මෙතන padding වැඩි කරාම තීරුව ලොකු වෙනවා
        backgroundColor: '#ffffff',
        borderBottom: '2px solid #e2e8f0'
      }}>
        <h1 style={{ margin: 0, fontSize: '32px', color: '#1e293b' }}>
          Welcome, {userName} 👋
        </h1>
        
        <button 
          onClick={handleLogout}
          style={{ 
            backgroundColor: '#dc2626', 
            color: '#ffffff', 
            border: 'none', 
            padding: '12px 24px', 
            borderRadius: '8px', 
            cursor: 'pointer', 
            fontWeight: 'bold', 
            fontSize: '15px' 
          }}
        >
          Logout
        </button>
      </div>

      {/* 2. Sidebar සහ Content කොටස */}
      <div style={{ display: 'flex', flex: 1 }}>
        <div style={{ width: '260px', backgroundColor: '#15803d', color: '#ffffff', padding: '25px' }}>
          {/* ඔයාගේ සයිඩ්බාර් එක */}
        </div>
        <div style={{ flex: 1, padding: '40px' }}>
          {/* ඔයාගේ Dashboard එකේ Content එක */}
        </div>
      </div>
  </div>
);}
